#include <iostream>
#include <string>

int main() {
    std::ios::sync_with_stdio(false);
    std::string bits;
    if (!std::getline(std::cin, bits)) return 0;

    /* S0 nothing, S1 saw 1, S2 saw 10, S3 saw 101 */
    int state = 0;
    std::string out;

    for (char c : bits) {
        if (c != '0' && c != '1') continue;
        int in = (c == '1') ? 1 : 0;
        int detect = 0;

        switch (state) {
            case 0: state = in ? 1 : 0; break;
            case 1: state = in ? 1 : 2; break;
            case 2: state = in ? 3 : 0; break;
            case 3:
                if (in) { detect = 1; state = 1; }
                else    { state = 2; }
                break;
            default: break;
        }
        out += detect ? '1' : '0';
    }

    std::cout << out << "\n";
    return 0;
}

