import sys

bits = sys.stdin.readline().strip()

state = 0          # 0 nothing, 1 saw "1", 2 saw "10", 3 saw "101"
out = []

for c in bits:
    if c not in "01":
        continue
    bit = 1 if c == "1" else 0
    detect = 0

    if state == 0:
        state = 1 if bit else 0
    elif state == 1:
        state = 1 if bit else 2
    elif state == 2:
        state = 3 if bit else 0
    elif state == 3:
        if bit:
            detect = 1
            state = 1
        else:
            state = 2

    out.append("1" if detect else "0")

print("".join(out))

