const bits = (readLines()[0] || '').trim();

let state = 0;          // 0 nothing, 1 saw "1", 2 saw "10", 3 saw "101"
const out = [];

for (const c of bits) {
  if (c !== '0' && c !== '1') continue;
  const bit = c === '1' ? 1 : 0;
  let detect = 0;

  if (state === 0)      state = bit ? 1 : 0;
  else if (state === 1) state = bit ? 1 : 2;
  else if (state === 2) state = bit ? 3 : 0;
  else if (state === 3) {
    if (bit) { detect = 1; state = 1; }
    else     { state = 2; }
  }

  out.push(detect ? '1' : '0');
}

print(out.join(''));
